		...blogCategories
			.map((category) => ({ category, count: countBlogCategory(category, articles) }))
			.filter(({ count }) => count > 0)
			.map(
				({ category, count }) =>
					`<li>${renderBlogSidebarLink('category', category, category, count)}</li>`
			)
	].join('\n');

	return `<p class="h4 mb-16">Категории</p>
