function replaceBlogStandardIndexCopy(html: string, articles: DayNightArticle[]) {
	let output = html
		.replaceAll('Blog Standard', 'Полезно и новини')
		.replaceAll('News', 'Полезно')
		.replaceAll('Home', 'Начало');

	output = replaceDivInnerByExactClass(
